function mergeIntervals(intervals) {
  const sorted = intervals.map((pair) => pair.slice()).sort((a, b) => a[0] - b[0]);
  const merged = [];
  let openStart = sorted[0][0];
  let openEnd = sorted[0][1];
  for (let i = 1; i < sorted.length; i += 1) {
    const [start, end] = sorted[i];
    if (start <= openEnd) {
      openEnd = Math.max(openEnd, end);
    } else {
      merged.push([openStart, openEnd]);
      openStart = start;
      openEnd = end;
    }
  }
  merged.push([openStart, openEnd]);
  return merged;
}

